window.TL = {"duration": 247.28, "scenes": [{"id": "intro", "label": "Title", "start": 0, "end": 14.08}, {"id": "what", "label": "What is a diagnostic assessment?", "start": 14.08, "end": 29.448}, {"id": "problem", "label": "Problems", "start": 29.448, "end": 50.475}, {"id": "adaptive", "label": "Adaptive diagnostic assessment", "start": 50.475, "end": 68.567}, {"id": "necessary", "label": "Only the necessary questions", "start": 68.567, "end": 77.777}, {"id": "benefit", "label": "Benefits", "start": 77.777, "end": 95.263}, {"id": "how", "label": "How it works", "start": 95.263, "end": 111.663}, {"id": "path", "label": "Algorithm example", "start": 111.663, "end": 148.998}, {"id": "validate", "label": "Validation step", "start": 148.998, "end": 180.016}, {"id": "quick", "label": "Quick Diagnosis", "start": 180.016, "end": 205.978}, {"id": "effects", "label": "Expected effects", "start": 205.978, "end": 238.449}, {"id": "outro", "label": "Thank you", "start": 238.449, "end": 247.28}], "lines": {"l1": {"text": "Hello. Today, I'd like to introduce the development direction and expected benefits of the online Adaptive Diagnostic Assessment for Self-Learning JEI Math.", "start": 3.0, "end": 12.83, "scene": "intro", "chunks": [{"text": "Hello. Today, I'd like to introduce the development direction and expected", "start": 3.0}, {"text": "benefits of the online Adaptive Diagnostic Assessment for Self-Learning JEI Math.", "start": 7.19}]}, "l2": {"text": "First, let me explain the challenges with our current diagnostic assessment.", "start": 14.88, "end": 19.12, "scene": "what", "chunks": [{"text": "First, let me explain the challenges with our current diagnostic assessment.", "start": 14.88}]}, "l3": {"text": "A diagnostic assessment is used to determine a learner's current level before the learner begins studying, and to prescribe a personalized learning program.", "start": 19.77, "end": 28.398, "scene": "what", "chunks": [{"text": "A diagnostic assessment is used to determine a learner's current level", "start": 19.77}, {"text": "before the learner begins studying, and to prescribe a personalized learning program.", "start": 23.52}]}, "l4": {"text": "Currently, accurate diagnosis requires every learner to answer the same set of questions.", "start": 30.248, "end": 35.618, "scene": "problem", "chunks": [{"text": "Currently, accurate diagnosis requires every learner to answer the same", "start": 30.248}, {"text": "set of questions.", "start": 34.408}]}, "l5": {"text": "While using a large number of questions can make the results more exact, it also places a significant burden on learners.", "start": 36.268, "end": 43.08, "scene": "problem", "chunks": [{"text": "While using a large number of questions can make the results more exact,", "start": 36.268}, {"text": "it also places a significant burden on learners.", "start": 40.238}]}, "l6": {"text": "As a result, the process can become less effective at identifying each learner's true starting point for learning.", "start": 43.73, "end": 49.425, "scene": "problem", "chunks": [{"text": "As a result, the process can become less effective at identifying each", "start": 43.73}, {"text": "learner's true starting point for learning.", "start": 47.36}]}, "l7": {"text": "To address this issue, we are developing an Adaptive Diagnostic Assessment.", "start": 51.275, "end": 55.685, "scene": "adaptive", "chunks": [{"text": "To address this issue, we are developing an Adaptive Diagnostic Assessment.", "start": 51.275}]}, "l8": {"text": "It is a responsive, high-precision diagnostic system in which the next question is adjusted in real time based on whether the learner answers correctly or incorrectly within each learning objective.", "start": 56.335, "end": 67.517, "scene": "adaptive", "chunks": [{"text": "It is a responsive, high-precision diagnostic system in which the next", "start": 56.335}, {"text": "question is adjusted in real time based on whether the learner answers", "start": 60.285}, {"text": "correctly or incorrectly within each learning objective.", "start": 64.425}]}, "l9": {"text": "The key is not to have learners answer every question, but to present only the questions that are necessary based on their responses.", "start": 69.367, "end": 76.727, "scene": "necessary", "chunks": [{"text": "The key is not to have learners answer every question,", "start": 69.367}, {"text": "but to present only the questions that are necessary based on their responses.", "start": 72.507}]}, "l10": {"text": "This approach improves both diagnostic efficiency and reliability, while also reducing the time required for the assessment.", "start": 78.577, "end": 85.407, "scene": "benefit", "chunks": [{"text": "This approach improves both diagnostic efficiency and reliability,", "start": 78.577}, {"text": "while also reducing the time required for the assessment.", "start": 82.427}]}, "l11": {"text": "In short, it lightens the burden of diagnosis while staying true to its core purpose: finding the learner's exact starting point for learning.", "start": 86.057, "end": 94.213, "scene": "benefit", "chunks": [{"text": "In short, it lightens the burden of diagnosis while staying true to its", "start": 86.057}, {"text": "core purpose: finding the learner's exact starting point for learning.", "start": 89.927}]}, "l12": {"text": "So, how does the Adaptive Diagnostic Assessment actually work?", "start": 96.063, "end": 99.793, "scene": "how", "chunks": [{"text": "So, how does the Adaptive Diagnostic Assessment actually work?", "start": 96.063}]}, "l13": {"text": "When a question is presented, a correct answer leads to a higher-level question, while an incorrect answer leads to a lower-level question designed to identify any missing concepts.", "start": 100.543, "end": 110.613, "scene": "how", "chunks": [{"text": "When a question is presented, a correct answer leads to a higher-level", "start": 100.543}, {"text": "question, while an incorrect answer leads to a lower-level question", "start": 104.003}, {"text": "designed to identify any missing concepts.", "start": 107.883}]}, "l14": {"text": "For example, instead of having a learner answer every question sequentially from No. 1 to No. 9, we first present a representative core question.", "start": 112.463, "end": 121.338, "scene": "path", "chunks": [{"text": "For example, instead of having a learner answer every question", "start": 112.463}, {"text": "sequentially from No. 1 to No. 9, we first present a representative core question.", "start": 115.733}]}, "l15": {"text": "If the learner answers incorrectly, the system moves down to lower-level concepts, such as No. 3 and then No. 1, to trace where the learning gap begins.", "start": 121.988, "end": 131.451, "scene": "path", "chunks": [{"text": "If the learner answers incorrectly, the system moves down to lower-level", "start": 121.988}, {"text": "concepts, such as No. 3 and then No. 1,", "start": 125.898}, {"text": "to trace where the learning gap begins.", "start": 128.838}]}, "l16": {"text": "On the other hand, if the learner answers correctly, the system moves up to No. 7 and then No. 9 to check how far the learner's understanding extends.", "start": 132.201, "end": 141.284, "scene": "path", "chunks": [{"text": "On the other hand, if the learner answers correctly,", "start": 132.201}, {"text": "the system moves up to No. 7 and then No. 9 to check how far the learner's", "start": 135.111}, {"text": "understanding extends.", "start": 139.911}]}, "l17": {"text": "In this way, we can minimize the number of questions while still gauging the learner's actual ability level.", "start": 142.034, "end": 147.948, "scene": "path", "chunks": [{"text": "In this way, we can minimize the number of questions while still gauging", "start": 142.034}, {"text": "the learner's actual ability level.", "start": 146.024}]}, "l18": {"text": "However, to maintain reliability even with fewer questions, the system also includes a validation step.", "start": 149.798, "end": 156.163, "scene": "validate", "chunks": [{"text": "However, to maintain reliability even with fewer questions,", "start": 149.798}, {"text": "the system also includes a validation step.", "start": 153.548}]}, "l19": {"text": "For each Representative Learning Objective, which represents the core learning goal, we prepare two additional similar questions for thorough evaluation.", "start": 156.813, "end": 165.563, "scene": "validate", "chunks": [{"text": "For each Representative Learning Objective,", "start": 156.813}, {"text": "which represents the core learning goal,", "start": 158.753}, {"text": "we prepare two additional similar questions for thorough evaluation.", "start": 161.073}]}, "l20": {"text": "Answering two out of three correctly results in an \"Understood\" status; otherwise, it is marked as \"Not Understood.\"", "start": 166.313, "end": 173.423, "scene": "validate", "chunks": [{"text": "Answering two out of three correctly results in an \"Understood\" status;", "start": 166.313}, {"text": "otherwise, it is marked as \"Not Understood.\"", "start": 170.643}]}, "l21": {"text": "It is a mechanism that trims the question count without sacrificing the reliability of the result.", "start": 174.173, "end": 178.966, "scene": "validate", "chunks": [{"text": "It is a mechanism that trims the question count without sacrificing the", "start": 174.173}, {"text": "reliability of the result.", "start": 177.503}]}, "l22": {"text": "We also prepared a 'Quick Diagnosis' option for faster use in the field.", "start": 180.816, "end": 184.606, "scene": "quick", "chunks": [{"text": "We also prepared a 'Quick Diagnosis' option for faster use in the field.", "start": 180.816}]}, "l23": {"text": "The Quick Diagnosis starts with Numbers and Operations, a foundational area of mathematics, and then provides a quick report on Numbers and Operations.", "start": 185.256, "end": 193.888, "scene": "quick", "chunks": [{"text": "The Quick Diagnosis starts with Numbers and Operations,", "start": 185.256}, {"text": "a foundational area of mathematics, and then provides a quick report on", "start": 188.126}, {"text": "Numbers and Operations.", "start": 192.506}]}, "l24": {"text": "Using this report, even before the full diagnosis is complete, you can discuss the learner's level of understanding in Numbers and Operations along with the direction for their next steps in learning.", "start": 194.538, "end": 204.928, "scene": "quick", "chunks": [{"text": "Using this report, even before the full diagnosis is complete,", "start": 194.538}, {"text": "you can discuss the learner's level of understanding in Numbers and", "start": 198.208}, {"text": "Operations along with the direction for their next steps in learning.", "start": 201.268}]}, "l25": {"text": "Now, let's look at how this assessment can help in practice.", "start": 206.778, "end": 210.451, "scene": "effects", "chunks": [{"text": "Now, let's look at how this assessment can help in practice.", "start": 206.778}]}, "l26": {"text": "First and foremost, it addresses one of the biggest pain points of the current diagnostic assessment: the excessive number of questions.", "start": 211.101, "end": 218.621, "scene": "effects", "chunks": [{"text": "First and foremost, it addresses one of the biggest pain points of the", "start": 211.101}, {"text": "current diagnostic assessment: the excessive number of questions.", "start": 214.601}]}, "l27": {"text": "With fewer questions, both learners and teachers can expect a lighter workload during diagnosis.", "start": 219.271, "end": 224.705, "scene": "effects", "chunks": [{"text": "With fewer questions, both learners and teachers can expect a lighter", "start": 219.271}, {"text": "workload during diagnosis.", "start": 222.981}]}, "l28": {"text": "This should make consultations and class operations run more smoothly as well.", "start": 225.355, "end": 229.66, "scene": "effects", "chunks": [{"text": "This should make consultations and class operations run more smoothly as well.", "start": 225.355}]}, "l29": {"text": "The assessment will first be applied to Self-Learning JEI Math, with the potential to expand to other subjects in the future.", "start": 230.31, "end": 237.299, "scene": "effects", "chunks": [{"text": "The assessment will first be applied to Self-Learning JEI Math,", "start": 230.31}, {"text": "with the potential to expand to other subjects in the future.", "start": 233.74}]}, "l30": {"text": "This concludes our introduction to the Adaptive Diagnostic Assessment.", "start": 239.249, "end": 242.949, "scene": "outro", "chunks": [{"text": "This concludes our introduction to the Adaptive Diagnostic Assessment.", "start": 239.249}]}, "l31": {"text": "Thank you.", "start": 243.699, "end": 244.333, "scene": "outro", "chunks": [{"text": "Thank you.", "start": 243.699}]}}, "order": ["l1", "l2", "l3", "l4", "l5", "l6", "l7", "l8", "l9", "l10", "l11", "l12", "l13", "l14", "l15", "l16", "l17", "l18", "l19", "l20", "l21", "l22", "l23", "l24", "l25", "l26", "l27", "l28", "l29", "l30", "l31"], "cues": {"adaptive": {"responsive": 56.695, "precision": 57.475, "realtime": 61.855, "next": 60.075, "correct": 64.475, "incorrect": 65.275}, "pathDown": [123.028, 127.248, 128.508], "pathUp": [134.461, 136.561, 137.781], "understood": 169.153, "notUnderstood": 172.293, "numbersOps": 186.836}};
